    if (g === 0) { a = ri(1, 8); b = ri(1, 9 - a); op = '+'; } else if (g === 1) { a = ri(2, 5); b = ri(1, 10); op = '·'; } else { a = ri(2, 10); b = ri(2, 10); op = '·'; }
    const res = op === '+' ? a + b : a * b, w = new Set();
    while (w.size < 2) { const d = op === '·' && Math.random() < .5 ? res + (Math.random() < .5 ? -a : a) : res + ri(1, 3) * (Math.random() < .5 ? -1 : 1); if (d > 0 && d !== res) w.add(d); }
