const MON_DE = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];
function aufItems(ym, g) {
  let sd = 0; for (const c of 'auf' + ym + ':' + g) sd = (sd * 31 + c.charCodeAt(0)) >>> 0;
  const rnd = () => ((sd = (sd * 1664525 + 1013904223) >>> 0) / 4294967296);
  const mix = (a) => { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const neu = AUF_NEU.filter((x) => x.m <= ym), fresh = neu.filter((x) => x.m === ym), old = neu.filter((x) => x.m !== ym);
  const pickN = mix(fresh).concat(mix(old)).slice(0, 3);
  const rest = simUnit(typeof fsTopicsOwned === 'function' ? fsTopicsOwned() : Object.keys(SIM_T), 4, 3, 'auf' + ym + g);
  return rest.concat(pickN.map(({ m, ...x }) => x));
}
function aufStart(ym) {
  if (!/^\d{4}-\d{2}$/.test(ym || '')) { const n = new Date(); ym = n.getFullYear() + '-' + String(n.getMonth() + 1).padStart(2, '0'); }
  const ki = SUBJ.findIndex((x) => x.k === 'ki');
  if (!PD(ki)) { location.href = '/'; return; }
  if (typeof FSP !== 'undefined' && FSP && !PAID && typeof fsAufAb === 'function') { const ab = fsAufAb(); if (!ab || ym < ab) { lpToast(ab ? 'Der erste Auffrischungstest kommt im ' + MON_DE[+ab.slice(5) - 1] + '.' : 'Den Auffrischungstest gibt es nach der bestandenen Prüfung.'); fsOpen(); return; } }
  if (st.grade < 0) { st.grade = 1; try { drawGrade(); drawLPCards(); } catch (e) {} }
  window._lob1 = 1; st.s = ki; history.replaceState(null, '', location.pathname + location.search + '#fuehrerschein'); if (typeof fsOpen === 'function') fsOpen(); /* Kursübersicht im Hintergrund, keine alte App */
  const run = () => { const items = aufItems(ym, st.grade); if (!items.length) { lpToast('Der Test lädt gerade nicht. Bitte gleich nochmal öffnen.'); return; } GT.t('Lektion gestartet', 'Auffrischungstest · ' + ym); startLesson(0, 0, 0, { items, title: 'Auffrischungstest ' + MON_DE[+ym.slice(5) - 1], kind: 'auf', sim: 1, si: ki, w: +ym.slice(5), g: st.grade, ym }); };
  (typeof LPX !== 'undefined' && LPX.st === 2) ? setTimeout(run, 250) : lpxLoad().then(run);
}
function aufEnd() {
  const C = LS.custom, secs = Math.round((Date.now() - LS.t0) / 1000), right = LS.first, tot = LS.total, acc = Math.round(right / tot * 100);
  sfx.win(); les.dataset.state = 'end';
  GT.t('Lektion fertig', 'Auffrischungstest · ' + C.ym + ' · ' + acc + ' %');
  const head = acc >= 90 ? 'Stark!' : acc >= 70 ? 'Gut gemacht!' : 'Fast!';
  const body = acc >= 90 ? 'Du bist im Internet richtig fit.' : acc >= 70 ? 'Schau dir die Fehler nochmal kurz an.' : 'Wiederhol ein paar Einheiten in der Übersicht, dann sitzt es wieder.';
  const e = document.createElement('div'); e.className = 'lesend fxend';
  e.innerHTML = `<div class="fxe"><div class="fxeh">${FX.logo}<span>Auffrischungstest ${MON_DE[+C.ym.slice(5) - 1]}</span></div><h3>${head}</h3><p>${body}</p>
    ${typeof fsStreak === 'function' && fsStreak() > 1 ? `<div class="fxestk">${FX.flame}<span><b>${fsStreak()} Tage</b> in Folge gelernt</span></div>` : ''}
    <div class="fxest"><div><b>${right} von ${tot}</b><small>richtig</small></div><div><b>${acc} %</b><small>Genauigkeit</small></div><div><b>${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}</b><small>Zeit</small></div></div>
    <p class="fxenote">Nächsten Monat kommt der nächste Test per Mail.</p>
    <div class="fxeb"><button class="fxbtn" data-a="back">Zur Übersicht ${FX.arrow}</button><button class="fxlnk" data-a="again">Nochmal machen</button></div></div>`;
  $('.lesin', les).appendChild(e);
  $('[data-a=back]', e).onclick = () => { closeLesson(); if (typeof fsOpen === 'function') fsOpen(); };
  $('[data-a=again]', e).onclick = () => { closeLesson(); setTimeout(() => aufStart(C.ym), 300); };
}

