/* ---------- Hintergrundmusik: je Bereich ein eigenes Stück, leise, weiche Übergänge, wird leiser wenn ein Tutor spricht ---------- */
const MUS = (() => {
  const U = '/grundschulmax/audio/music/', VOL = { lobby: .45, path: .35, game: .28, hw: .3 }, START = .45;
  const A = {}; let cur = '', want = '', armed = false, duck = 1, duckUntil = 0;
  const IOS = /iP(hone|ad|od)/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
  let MC = null; const wire = (a) => { if (!IOS || a._g) return; try { MC = MC || new (window.AudioContext || window.webkitAudioContext)(); if (MC.state === 'suspended') MC.resume(); const g = MC.createGain(); g.gain.value = 0; MC.createMediaElementSource(a).connect(g).connect(MC.destination); a._g = g; a.volume = 1; } catch (e) {} };
  /* Musik ist bei jedem Öffnen an. Ausschalten gilt nur, bis die Seite neu geladen wird. */
  try { localStorage.removeItem('gsm-music'); } catch (e) {}
  let MV = '1'; try { sessionStorage.removeItem('gsm-music'); } catch (e) {}
  const mg = () => MV;
  const ms = (v) => { MV = v; };
  const on = () => mg() !== '0' && !document.hidden;
  const get = (k) => { if (!A[k]) { const a = new Audio(U + (k === 'start' ? 'lobby' : k) + '.mp3'); a.loop = true; a.preload = 'none'; a.volume = 0; a._v = 0; A[k] = a; } return A[k]; };
  function scene() {
    /* Musik nur noch im Spielbereich (body.gsmspiel). Führerschein, Lektionen und Quiz bleiben ohne Musik. */
    if (!document.body.classList.contains('gsmspiel')) return '';
    if (document.body.classList.contains('lobon')) return 'lobby';
    const les = document.querySelector('.les.on'), stg = document.querySelector('#stage.open');
    if (les || stg) return 'game';
    const scr = document.body.dataset.screen;
    if (scr === 'start' || scr === 'klasse') return '';
    if (scr !== 'spiel') return '';
    if (typeof st !== 'undefined' && st.nav === 'hw') return 'hw';
    if (typeof st !== 'undefined' && (st.nav === 'profile' || st.nav === 'parents')) return 'path';
    return 'path';
  }
  function tick() {
    want = armed && on() ? scene() : '';
    const talking = (typeof curAudio !== 'undefined' && curAudio && !curAudio.paused) || (typeof hwSrc !== 'undefined' && hwSrc);
    duck += ((talking ? .3 : 1) - duck) * .35;
    for (const k of [...Object.keys(VOL), 'start']) {
      const a = A[k], tgt = k === want ? (VOL[k] ?? START) * duck * (Date.now() < duckUntil ? .25 : 1) : 0; if (!a && !tgt) continue;
      const x = get(k); x._v += (tgt - x._v) * .18; if (Math.abs(x._v - tgt) < .003) x._v = tgt;
      const vv = Math.max(0, Math.min(1, x._v)); if (x._g) x._g.gain.value = vv; else x.volume = vv;
      if (x._v > .001 && x.paused) { const r = x.play(); if (r && r.then) r.then(() => { ok = true; }).catch(() => { ok = false; if (SAF) primed = false; }); }
      if (x._v <= .001 && !x.paused) x.pause();
    }
    cur = want;
  }
  /* Freischalten: bei jeder echten Nutzer-Geste (Finger loslassen, Klick, Taste), bis wirklich Musik läuft.
     Safari (iPhone, iPad, Mac) gibt jede Tonspur einzeln frei, deshalb dort alle Spuren in der Geste kurz anstoßen. */
  const SAF = IOS || (/Safari\//.test(navigator.userAgent) && !/Chrome|Chromium|CriOS|FxiOS|Android|Edg\//.test(navigator.userAgent));
  let primed = false, ok = false;
  const prime = () => { primed = true; for (const k of [...Object.keys(VOL), 'start']) { const x = get(k); wire(x); x.preload = 'auto'; if (!x.paused) continue; const r = x.play(); if (r && r.then) r.then(() => { if (x._v <= .001) x.pause(); }).catch(() => { primed = false; }); } };
  const arm = () => { armed = true; if (SAF && !primed) prime(); if (MC && MC.state === 'suspended') MC.resume(); tick(); };
  const gest = () => { const a = A[want]; if (!armed || !ok || !primed && SAF || (a && a.paused && a._v > .001)) arm(); };
  ['pointerup', 'touchend', 'mousedown', 'click', 'keydown'].forEach((e) => addEventListener(e, gest, { passive: true, capture: true }));
  setInterval(tick, 120);
  document.addEventListener('visibilitychange', tick);
  const hm = () => { const b = document.getElementById('hmus'); if (!b) return; const o = mg() !== '0'; b.innerHTML = `<svg class="i"><use href="#i-${o ? 'snd' : 'mute'}"/></svg><span>Musik</span>`; b.classList.toggle('off', !o); };
  setTimeout(() => { const b = document.getElementById('hmus'); if (b) b.onclick = () => { armed = true; ms(mg() !== '0' ? '0' : '1'); hm(); tick(); }; hm(); }, 0);
  return {
    on: () => mg() !== '0',
    set(v) { ms(v ? '1' : '0'); tick(); hm(); },
    _s: () => ({ cur, want, armed, duck: +duck.toFixed(2), v: Object.fromEntries(Object.entries(A).map(([k, a]) => [k, [+a._v.toFixed(3), a.paused]])) }),
    /* kurz leiser, damit ein wichtiger Klang (Hüpfen auf dem Pfad, Gewonnen) durchkommt */
    duck(ms = 900) { duckUntil = Math.max(duckUntil, Date.now() + ms); const a = A[cur]; if (a && a._v > 0) { a._v = Math.min(a._v, (VOL[cur] ?? START) * .25); a.volume = a._v; } },
    toggle() { const v = this.on() ? '0' : '1'; ms(v); tick(); hm(); return v === '1'; },
  };
})();

